      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was provided describing how similar systematic reviews exist and how the need for the current review was explained via updates/replications of previous reviews."
